.chapter-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink, #1a1a1a);
  background: var(--paper, #fafafa);
}

.chapter-header {
  margin-bottom: 3rem;
  border-bottom: 2px solid var(--line, #e0e0e0);
  padding-bottom: 1rem;
}

.chapter-header h1 {
  font-size: 2.5rem;
  font-weight: 700;
  margin: 0 0 0.5rem 0;
  color: var(--ink, #1a1a1a);
}

.lead {
  font-size: 1.25rem;
  color: var(--muted, #666);
  margin: 0;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  margin-bottom: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

.narrative-panel {
  background: var(--paper, #fafafa);
  padding: 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--line, #e0e0e0);
}

.narrative-panel h2 {
  font-size: 1.5rem;
  margin-top: 0;
  color: var(--ink, #1a1a1a);
}

.narrative-panel p {
  line-height: 1.6;
  margin-bottom: 1rem;
  font-size: 1rem;
}

.source-citation {
  margin-top: 1.5rem;
  display: flex;
  gap: 0.5rem;
}

.source-btn {
  background: var(--accent, #2563eb);
  color: white;
  border: none;
  padding: 0.5rem 1rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.875rem;
  transition: background 0.2s;
}

.source-btn:hover {
  background: #1d4ed8;
}

.interaction-panel {
  background: var(--paper, #fafafa);
  padding: 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--line, #e0e0e0);
}

.model-comparison {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.model-card {
  background: white;
  border: 2px solid var(--line, #e0e0e0);
  border-radius: 8px;
  padding: 1rem;
  transition: all 0.3s ease;
}

.model-card.parametric {
  border-color: #3b82f6;
}

.model-card.hybrid {
  border-color: #f59e0b;
}

.model-card h3 {
  margin: 0 0 1rem 0;
  font-size: 1.125rem;
  color: var(--ink, #1a1a1a);
}

.model-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 1rem;
  background: #f9fafb;
  border-radius: 4px;
  margin-bottom: 1rem;
  flex-wrap: wrap;
}

.weight-block, .input-box, .retriever-box, .doc-box, .output-box {
  padding: 0.5rem 0.75rem;
  background: white;
  border: 1px solid var(--line, #e0e0e0);
  border-radius: 4px;
  font-size: 0.875rem;
  text-align: center;
  min-width: 60px;
}

.weight-block {
  background: #dbeafe;
  border-color: #3b82f6;
}

.retriever-box {
  background: #fef3c7;
  border-color: #f59e0b;
}

.doc-box {
  background: #fef3c7;
  border-color: #f59e0b;
}

.arrow {
  color: var(--muted, #666);
  font-weight: bold;
}

.status-indicator {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  background: #f9fafb;
  border-radius: 4px;
  font-size: 0.875rem;
}

.status-label {
  color: var(--muted, #666);
}

.status-value {
  font-weight: 600;
  padding: 0.25rem 0.5rem;
  border-radius: 4px;
}

#status-parametric .status-value {
  background: #fee2e2;
  color: #dc2626;
}

#status-hybrid .status-value {
  background: #dcfce7;
  color: #16a34a;
}

.control-panel {
  text-align: center;
}

.action-btn {
  background: var(--accent, #2563eb);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 6px;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s;
  font-weight: 500;
}

.action-btn:hover {
  background: #1d4ed8;
  transform: translateY(-1px);
}

.action-btn:active {
  transform: translateY(0);
}

.feedback-area {
  margin-top: 1rem;
  padding: 0.75rem;
  border-radius: 4px;
  font-size: 0.875rem;
  min-height: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.feedback-area.success {
  background: #dcfce7;
  color: #16a34a;
  border: 1px solid #86efac;
}

.feedback-area.warning {
  background: #fee2e2;
  color: #dc2626;
  border: 1px solid #fca5a5;
}

.key-points {
  background: white;
  padding: 1.5rem;
  border-radius: 8px;
  border: 1px solid var(--line, #e0e0e0);
  margin-top: 2rem;
}

.key-points h3 {
  margin: 0 0 1rem 0;
  color: var(--ink, #1a1a1a);
  font-size: 1.25rem;
}

.key-points ul {
  margin: 0;
  padding-left: 1.5rem;
  line-height: 1.8;
  color: var(--ink, #1a1a1a);
}

.key-points li {
  margin-bottom: 0.5rem;
}

javascript:
(function() {
  'use strict';

  const btnUpdate = document.getElementById('btn-update-knowledge');
  const feedbackArea = document.getElementById('feedback-area');
  const statusParametric = document.getElementById('status-parametric');
  const statusHybrid = document.getElementById('status-hybrid');
  const modelParametric = document.getElementById('model-parametric');
  const modelHybrid = document.getElementById('model-hybrid');

  let isUpdating = false;

  function updateKnowledge() {
    if (isUpdating) return;
    isUpdating = true;

    // 清除之前的反馈
    feedbackArea.className = 'feedback-area';
    feedbackArea.textContent = '';

    // 模拟更新过程
    setTimeout(() => {
      // 更新纯参数模型状态
      const parametricValue = statusParametric.querySelector('.status-value');
      parametricValue.textContent = '需重新训练';
      parametricValue.style.background = '#fee2e2';
      parametricValue.style.color = '#dc2626';

      // 更新混合模型状态
      const hybridValue = statusHybrid.querySelector('.status-value');
      hybridValue.textContent = '替换索引';
      hybridValue.style.background = '#dcfce7';
      hybridValue.style.color = '#16a34a';

      // 显示反馈
      feedbackArea.textContent = '知识更新完成：纯参数模型需重新训练，混合模型仅需替换索引';
      feedbackArea.classList.add('success');

      // 添加视觉反馈
      modelParametric.style.transform = 'scale(1.02)';
      modelHybrid.style.transform = 'scale(1.02)';

      setTimeout(() => {
        modelParametric.style.transform = 'scale(1)';
        modelHybrid.style.transform = 'scale(1)';
        isUpdating = false;
      }, 300);

    }, 800);
  }

  // 绑定事件
  btnUpdate.addEventListener('click', updateKnowledge);

  // 键盘支持
  btnUpdate.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      updateKnowledge();
    }
  });

  // 初始化状态
  function init() {
    // 确保初始状态正确
    const parametricValue = statusParametric.querySelector('.status-value');
    parametricValue.textContent = '需重新训练';
    parametricValue.style.background = '#fee2e2';
    parametricValue.style.color = '#dc2626';

    const hybridValue = statusHybrid.querySelector('.status-value');
    hybridValue.textContent = '替换索引';
    hybridValue.style.background = '#dcfce7';
    hybridValue.style.color = '#16a34a';
  }

  init();
})();
